contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint thisBefore = address(this).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint thisAfter = address(this).balance;

        assert(
            countAfter == countBefore &&
            ((!reverted && balBefore >= value && balAfter == balBefore - value && thisAfter == thisBefore + value) ||
             (reverted && balAfter == balBefore && thisAfter == thisBefore))
        );
    }

    receive() external payable {}
}

