contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        uint balBefore = address(c).balance;
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint thisBefore = address(this).balance;
        bool reverted;
        try c.withdraw(value) { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        uint256 countAfter;
        try c.depositsCount() returns (uint256 __r) { countAfter = __r; } catch { return; }
        uint thisAfter = address(this).balance;
        assertTrue(countAfter == countBefore &&
            ((!reverted && balBefore >= value && balAfter == balBefore - value && thisAfter == thisBefore + value) ||
             (reverted && balAfter == balBefore && thisAfter == thisBefore)));
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

